/* eslint-disable no-console -- CLI script */
/**
 * Lint ratchet for architectural rules (audit item A5).
 *
 * Runs oxlint with ONLY `.oxlintrc.boundaries.json` (import cycles, layer and feature boundaries, `.server` value
 * imports; generated by scripts/gen-oxlintrc.mjs), then compares the number of violations per file and rule with
 * `lint-baseline/boundaries.json`.
 *
 *   pnpm lint:ratchet            fail if any count goes UP or a new file appears
 *   pnpm lint:ratchet:update     rewrite the baseline from the current tree
 *
 * Counts that go DOWN do not fail; the script prints a hint to shrink the baseline (run with --update and commit the
 * smaller file). The goal is an empty baseline, after which the rules can move into `.oxlintrc.json` at `error`.
 *
 * Rule keys: `import/no-cycle`, and for `no-restricted-imports` a short tag derived from the module and the file
 * (`lib-imports-components`, `shared-imports-feature`, `server-value-import`). Unlike ESLint's rule, oxlint also
 * counts dynamic `import()` calls, so `lib/` files that lazy-load components are counted here.
 */
import { spawnSync } from 'node:child_process';
import fs from 'node:fs';
import path from 'node:path';

const ROOT = process.cwd();
const BASELINE = path.join(ROOT, 'lint-baseline', 'boundaries.json');
const TARGETS = ['components', 'lib', 'hooks', 'stores', 'features'];
const OXLINT = path.join(ROOT, 'node_modules', 'oxlint', 'bin', 'oxlint');

interface Entry {
  file: string;
  rule: string;
  count: number;
}

interface Diagnostic {
  code: string;
  message: string;
  filename: string;
}

/** oxlint reports `'<module>' import is restricted from being used by a pattern.`, so the rule is derived from the module. */
function ruleKey(d: Diagnostic): string {
  if (d.code === 'import(no-cycle)') return 'import/no-cycle';
  if (d.code !== 'eslint(no-restricted-imports)') return d.code;
  const module = /^'([^']+)'/.exec(d.message)?.[1] ?? '';
  if (/\.server(\.ts)?$/.test(module)) return 'boundaries/server-value-import';
  // lib/ and a feature's engine/server/net are the lower layer: they must not value-import components
  const libHalf = /^(lib\/|features\/[^/]+\/(engine|server|net)\/)/.test(d.filename);
  if (libHalf && /^@\/components(\/|$)/.test(module)) return 'boundaries/lib-imports-components';
  // otherwise a shared dir (components/ui, components/shared, hooks, stores, lib/shared) reaching into a feature
  return 'boundaries/shared-imports-feature';
}

function collect(): Entry[] {
  const run = spawnSync(process.execPath, [OXLINT, '-c', '.oxlintrc.boundaries.json', '-f', 'json', ...TARGETS], {
    cwd: ROOT,
    encoding: 'utf8',
    maxBuffer: 256 * 1024 * 1024,
  });
  if (run.error || !run.stdout) throw new Error(`oxlint did not run: ${run.error?.message ?? run.stderr}`);
  const diagnostics = (JSON.parse(run.stdout) as { diagnostics: Diagnostic[] }).diagnostics;
  const counts = new Map<string, Entry>();
  for (const d of diagnostics) {
    const file = d.filename.split(path.sep).join('/');
    const rule = ruleKey(d);
    const key = `${file}\0${rule}`;
    const e = counts.get(key) ?? { file, rule, count: 0 };
    e.count += 1;
    counts.set(key, e);
  }
  return [...counts.values()].sort((a, b) =>
    a.file === b.file ? a.rule.localeCompare(b.rule) : a.file.localeCompare(b.file),
  );
}

function readBaseline(): Entry[] {
  try {
    return JSON.parse(fs.readFileSync(BASELINE, 'utf8')).violations as Entry[];
  } catch {
    return [];
  }
}

function main() {
  const update = process.argv.includes('--update');
  const t0 = Date.now();
  const current = collect();
  const secs = ((Date.now() - t0) / 1000).toFixed(1);

  if (update) {
    const totals: Record<string, number> = {};
    for (const e of current) totals[e.rule] = (totals[e.rule] ?? 0) + e.count;
    fs.mkdirSync(path.dirname(BASELINE), { recursive: true });
    fs.writeFileSync(
      BASELINE,
      JSON.stringify(
        {
          note: 'Generated by `pnpm lint:ratchet:update`. Counts may only go down. See scripts/check-lint-ratchet.ts.',
          totals,
          violations: current,
        },
        null,
        2,
      ) + '\n',
    );
    console.log(`lint:ratchet baseline written (${current.length} file/rule entries, ${secs}s)`);
    console.log(totals);
    return;
  }

  const base = new Map(readBaseline().map((e) => [`${e.file}\0${e.rule}`, e.count]));
  const seen = new Set<string>();
  const worse: string[] = [];
  const better: string[] = [];
  for (const e of current) {
    const key = `${e.file}\0${e.rule}`;
    seen.add(key);
    const was = base.get(key);
    if (was === undefined) worse.push(`  NEW   ${e.file}  ${e.rule}  (0 -> ${e.count})`);
    else if (e.count > was) worse.push(`  UP    ${e.file}  ${e.rule}  (${was} -> ${e.count})`);
    else if (e.count < was) better.push(`  ${e.file}  ${e.rule}  (${was} -> ${e.count})`);
  }
  for (const [key, was] of base) {
    if (!seen.has(key)) {
      const [file, rule] = key.split('\0');
      better.push(`  ${file}  ${rule}  (${was} -> 0)`);
    }
  }

  if (worse.length) {
    console.error(`lint:ratchet FAILED: architectural violations increased (${secs}s)\n${worse.join('\n')}`);
    console.error('\nFix the new import (see scripts/gen-oxlintrc.mjs for each rule). Do not raise the baseline.');
    process.exit(1);
  }
  if (better.length) {
    console.log(
      `lint:ratchet: ${better.length} entries improved; shrink the baseline with \`pnpm lint:ratchet:update\` and commit it:\n${better.join('\n')}`,
    );
  }
  console.log(`lint:ratchet OK (${current.length} baselined file/rule entries, ${secs}s)`);
}

try {
  main();
} catch (err) {
  console.error(err);
  process.exit(2);
}
